/**
 * 구매자에게 주문 총액의 1%를 포인트로 적립하고 혜택 알림을 보냅니다.
 * 주문당 한 번만 지급하며, 적립액이 0포인트면 지급하지 않습니다.
 *
 * @param order 배송 완료된 주문
 */
private void rewardPurchasePoints(Order order) {
    if (order.isPointRewarded()) {
        log.debug("구매 적립 포인트 이미 지급됨: orderId={}", order.getId());
        return;
    }

    int rewardPoints = order.getTotalAmount() / PURCHASE_REWARD_DIVISOR;
    if (rewardPoints <= 0) {
        log.debug("구매 적립 포인트 없음 (0포인트): orderId={}", order.getId());
        return;
    }

    User buyer = order.getUser();
    order.markPointRewarded();
    pointRepository.save(new Point(buyer, rewardPoints, "구매 적립 (주문 ID: " + order.getId() + ")"));

    notificationCommandService.createNotification(
            buyer.getId(),
            NotificationCategory.SHOPPING,
            NotificationType.BENEFIT,
            String.format("구매 적립 포인트 %,dP가 적립되었습니다. 주문 ID: %d", rewardPoints, order.getId())
    );

    log.info("구매 적립 포인트 지급: userId={}, orderId={}, points={}", buyer.getId(), order.getId(), rewardPoints);
}

